function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Cashier' || !Array.isArray(args[0]) || args[0].length !== 4) return 'Start with Cashier(n, discount, products, prices).';
  const [n, discount, products, prices] = args[0];
  const whole = (v, lo, hi) => Number.isInteger(v) && v >= lo && v <= hi;
  if (!whole(n, 1, 10000)) return 'n is a whole number from 1 to 10^4.';
  if (!whole(discount, 0, 100)) return 'discount is a whole number from 0 to 100.';
  if (!Array.isArray(products) || products.length < 1 || products.length > 200) return 'products needs 1 to 200 items.';
  if (!Array.isArray(prices) || prices.length !== products.length) return 'prices must have one price per product.';
  if (products.some(id => !whole(id, 1, 200))) return 'Each product ID is from 1 to 200.';
  if (new Set(products).size !== products.length) return 'Product IDs in the catalogue must be distinct.';
  if (prices.some(p => !whole(p, 1, 1000))) return 'Each price is from 1 to 1000.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls to getBill.';
  const known = new Set(products);
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'getBill' || !Array.isArray(args[i]) || args[i].length !== 2) return 'Only getBill(product, amount) can follow the constructor.';
    const [product, amount] = args[i];
    if (!Array.isArray(product) || product.length < 1 || product.length > products.length) return 'A basket holds 1 to products.length items.';
    if (!Array.isArray(amount) || amount.length !== product.length) return 'amount must have one entry per basket item.';
    if (product.some(id => !known.has(id))) return 'Every basket item must be in the catalogue.';
    if (new Set(product).size !== product.length) return 'Items in a basket must be distinct.';
    if (amount.some(a => !whole(a, 1, 1000))) return 'Each amount is from 1 to 1000.';
  }
  return null;
}

