class Cashier {
  constructor(n, discount, products, prices) {
    this.n = n;
    this.discount = discount;
    this.priceOf = new Map();
    for (let i = 0; i < products.length; i++) {
      this.priceOf.set(products[i], prices[i]);
    }
    this.customers = 0;
  }

  getBill(product, amount) {
    this.customers++;
    let bill = 0;
    for (let j = 0; j < product.length; j++) {
      bill += this.priceOf.get(product[j]) * amount[j];
    }
    if (this.customers % this.n === 0) {
      bill = (bill * (100 - this.discount)) / 100;
    }
    return bill;
  }
}

