class Cashier {
  constructor(n, discount, products, prices) {
    // Keep the catalogue as given and every past charge; search the catalogue item by item.
    this.rule = { n, factor: (100 - discount) / 100 };
    this.products = products.slice();
    this.prices = prices.slice();
    this.history = [];
  }
  getBill(product, amount) {
    let total = 0;
    product.forEach((id, j) => {
      const where = this.products.indexOf(id);
      for (let k = 0; k < amount[j]; k++) total += this.prices[where];
    });
    const position = this.history.length + 1;
    const charge = position % this.rule.n === 0 ? total * this.rule.factor : total;
    this.history.push(charge);
    return charge;
  }
}

