function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const ids = shuffle(Array.from({ length: 200 }, (_, i) => i + 1));
  const count = large ? (rand() < 0.5 ? 200 : 20 + pick(181)) : 1 + pick(6);
  const products = ids.slice(0, count);
  const prices = products.map(() => (large || rand() < 0.5 ? 1 + pick(1000) : 1 + pick(10)));
  const n = large ? [1, 2, 7, 50, 10000][pick(5)] : 1 + pick(4);
  const discount = [0, 100, 50, 1 + pick(99), 1 + pick(99)][pick(5)];
  const calls = large ? 499 : 1 + pick(10);
  const operations = ['Cashier'];
  const args = [[n, discount, products, prices]];
  let budget = 15000 - 2 * count;
  for (let c = 0; c < calls; c++) {
    let length = large && rand() < 0.05 ? count : 1 + pick(Math.min(count, large ? 20 : 4));
    if (2 * length > budget - 2 * (calls - c)) length = 1;
    budget -= 2 * length;
    const product = shuffle(products.slice()).slice(0, length);
    const amount = product.map(() => (large || rand() < 0.3 ? 1 + pick(1000) : 1 + pick(5)));
    operations.push('getBill');
    args.push([product, amount]);
  }
  return [operations, args];
}
